  (* [comment removed for export] *)
  Lemma rbU_loop : forall fuel m ns ns' (p pp : Z) (x1 t0 t1 t2 a3 a4 a5 a6 a7 s2x t3 t4 t5 t6 : word),
    rb_ctx m ns -> cols_ok [] ns ->
    (oloop fuel (rb_body h) (ns, (p, pp)) ≫= (λ ns2, rb_end ns2 h)) = Some ns' ->
    0 <= p < 2^64 -> 0 <= pp < 2^64 -> pp <> h ->
    evt usegs (POST ns')
      (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (Z_to_bv 64 h) (Z_to_bv 64 p)
               (Z_to_bv 64 pp) (Z_to_bv 64 2) (Z_to_bv 64 1) a3 a4 a5 a6 a7
